const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),path=require('node:path');
const root=path.resolve(__dirname,'..');
function geometry(){const source=fs.readFileSync(path.join(root,'tile-game-assets/bronze-age-world/tile-game/app.mjs'),'utf8');const code=source.match(/function terrain\(t,color\)\{[^\n]+/)[0];class BufferGeometry{setAttribute(k,v){this[k]=v;return this;}setIndex(v){this.indices=v;}computeVertexNormals(){}}class Color{constructor(){this.r=this.g=this.b=.5;}set(){return this;}multiplyScalar(){return this;}}const context={T:{BufferGeometry,Color,Float32BufferAttribute:class{constructor(array){this.array=array;}}},R:12,height:(t,x,z)=>Math.sin(x*.03)+t.level*4,ground:(x,z)=>Math.sin(x*.03),center:()=>({x:0,z:0})};vm.createContext(context);return vm.runInContext(code+';terrain({q:0,r:0,level:0},"green")',context);}
test('game hex is closed and side triangles face outward',()=>{const g=geometry(),p=g.position.array,edges=new Map();let sides=0,bottom=0;for(let i=0;i<g.indices.length;i+=3){const ids=g.indices.slice(i,i+3),v=ids.map(n=>p.slice(n*3,n*3+3));for(let j=0;j<3;j++){const a=ids[j],b=ids[(j+1)%3],key=[Math.min(a,b),Math.max(a,b)].join(':');edges.set(key,(edges.get(key)||0)+1);}const [a,b,c]=v,u=b.map((n,j)=>n-a[j]),w=c.map((n,j)=>n-a[j]),n=[u[1]*w[2]-u[2]*w[1],u[2]*w[0]-u[0]*w[2],u[0]*w[1]-u[1]*w[0]];if(ids.some(n=>n>=385)&&ids.some(n=>n<385)){assert.ok(n[0]*(a[0]+b[0]+c[0])+n[2]*(a[2]+b[2]+c[2])>0);sides++;}if(ids.every(n=>n>=385)){assert.ok(n[1]<0);bottom++;}}assert.equal(sides,96);assert.equal(bottom,48);assert.ok([...edges.values()].every(n=>n===2));});
test('selection and layout changes preserve camera, lifting hides original and reveals ground',()=>{const s=fs.readFileSync(path.join(root,'board.js'),'utf8');assert.match(s,/dragHidden.push\(\[g,g.visible\]\);g.visible=false/);assert.match(s,/surface.material.visible=true;surface.material.depthWrite=true/);assert.match(s,/for\(const\[g,visible\]of dragHidden\)g.visible=visible/);assert.doesNotMatch(s.match(/new ResizeObserver\([^\n]+/)[0],/fit\(/);assert.doesNotMatch(s.match(/function setMode\([^\n]+/)[0],/;fit\(/);assert.match(s,/if\(cameraOwnsPointer\(e\)\|\|busy\)return/);});
